insert into publishers (name) values ('Cohere') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Cohere', 'cohere', p.id, 'Enterprise LLM platform for RAG, agents and language APIs.', 'Cohere offers Command models, embeddings and tools for building production language applications.', 'https://cohere.com', 'published', 'Freemium', 'Trial / paid usage', true, false, false, ARRAY['enterprise', 'rag', 'embeddings']::text[], ARRAY['Enterprise focus', 'RAG tooling']::text[], ARRAY['Best with API integration work']::text[], ARRAY['Enterprises', 'Developers']::text[], current_date from publishers p where p.name = 'Cohere' on conflict (slug) do nothing;
insert into publishers (name) values ('Amazon') on conflict (name) do nothing; insert into tools (name, slug, publisher_id, summary, description, official_url, status, pricing_model, price_display, api_available, open_source, local_available, keywords, strengths, limits, audience, last_verified_at) select 'Amazon Q', 'amazon-q', p.id, 'AWS generative AI assistant for building and business work.', 'Amazon Q helps developers and employees with AWS, coding and workplace questions inside Amazon services.', 'https://aws.amazon.com/q/', 'published', 'Paid', 'To verify', true, false, false, ARRAY['aws', 'assistant', 'enterprise']::text[], ARRAY['AWS ecosystem integration']::text[], ARRAY['Centered on Amazon/AWS workflows']::text[], ARRAY['Developers', 'Enterprises']::text[], current_date from publishers p where p.name = 'Amazon' on conflict (slug) do nothing;
